-- Textes des 21 offres (résumé de carte + description de fiche), rédigés à la demande du
-- propriétaire le 17/11/2026. Ils décrivent la prestation sans avancer aucun fait sur
-- l'entreprise (ni chiffre, ni délai, ni référence, ni prix). Modifiables dans l'administration.
update public.activity_services s
set summary = v.summary, description = v.description
from (values
  ('travaux-de-terrassement-et-de-remblayage',
   'Décapage, déblais, remblais et mise à niveau des sols pour préparer vos terrains à construire ou à aménager.',
   'Nous préparons le sol avant tout projet : décapage de la terre végétale, déblais et remblais, compactage et mise à niveau des plateformes. Ces travaux donnent au terrain l''assise nécessaire aux constructions, voiries et aménagements à venir.'),
  ('ouverture-et-amenagement-de-routes',
   'Ouverture de pistes et de voies d''accès, profilage et rechargement pour desservir vos sites et lotissements.',
   'Nous ouvrons et aménageons les voies qui desservent vos terrains : tracé et ouverture de pistes, profilage de la chaussée, rechargement en latérite et gestion de l''écoulement des eaux. L''objectif : des accès praticables pour vos chantiers et vos futurs occupants.'),
  ('preparation-et-viabilisation-de-terrains',
   'Débroussaillage, nettoyage et préparation des terrains pour accueillir réseaux, voiries et constructions.',
   'Nous rendons vos terrains exploitables : débroussaillage, dessouchage, nettoyage du site, délimitation des emprises et préparation des tranchées pour les réseaux. Une étape indispensable avant tout lotissement ou projet de construction.'),
  ('travaux-de-construction',
   'Réalisation de bâtiments et d''ouvrages, du gros œuvre aux finitions, selon les plans de votre projet.',
   'Nous réalisons vos projets de construction selon vos plans : fondations, gros œuvre, maçonnerie et finitions. Chaque projet fait l''objet d''un échange préalable pour préciser vos besoins, puis d''un devis adapté.'),
  ('fourniture-de-laterite-et-materiaux-de-construction',
   'Approvisionnement en latérite, sable, gravier et matériaux de construction, livrés sur votre chantier.',
   'Nous approvisionnons vos chantiers en latérite et en matériaux de construction : sable, gravier, moellons et autres fournitures selon vos besoins. Indiquez-nous la nature, la quantité et le lieu de livraison pour recevoir un devis.'),
  ('location-et-mobilisation-d-engins-de-chantier',
   'Mise à disposition et mobilisation d''engins pour vos travaux de terrassement, de transport et d''aménagement.',
   'Nous mettons à votre disposition des engins de chantier pour vos travaux : terrassement, chargement, transport de matériaux et aménagement. Précisez la nature des travaux, le lieu et la durée envisagée pour que nous étudiions votre demande.'),
  ('travaux-d-amenagement-et-de-developpement-de-sites',
   'Aménagement global de sites : organisation des espaces, voiries, plateformes et préparation au développement.',
   'Nous accompagnons l''aménagement de sites dans leur ensemble : organisation des espaces, création des voiries internes, préparation des plateformes et coordination des travaux, pour rendre un site prêt à accueillir son projet.'),
  ('achat-et-vente-de-terrains',
   'Mise en relation et accompagnement pour l''achat ou la vente de terrains, dans le respect des démarches foncières.',
   'Nous accompagnons l''achat et la vente de terrains : recherche de biens correspondant à vos critères, présentation des terrains disponibles et suivi des démarches. Toute transaction s''appuie sur les vérifications foncières d''usage.'),
  ('lotissement-et-amenagement-foncier',
   'Découpage de terrains en parcelles, tracé des voies et aménagement des lotissements.',
   'Nous transformons de grands terrains en lotissements organisés : étude du découpage, bornage des parcelles, tracé et ouverture des voies de desserte, et aménagement des espaces communs.'),
  ('commercialisation-de-parcelles',
   'Présentation et vente de parcelles issues de nos projets d''aménagement, avec un accompagnement à chaque étape.',
   'Nous commercialisons des parcelles issues de projets d''aménagement : présentation des lots, visite des sites et accompagnement de l''acquéreur dans ses démarches. Les disponibilités sont communiquées sur demande.'),
  ('recherche-et-acquisition-de-domaines-fonciers',
   'Identification et acquisition de domaines fonciers adaptés à vos projets résidentiels, agricoles ou industriels.',
   'Nous identifions des domaines fonciers adaptés à votre projet, qu''il soit résidentiel, agricole ou industriel, et vous accompagnons dans les démarches d''acquisition, depuis la prospection jusqu''aux vérifications foncières.'),
  ('developpement-de-projets-immobiliers',
   'Conception et conduite de projets immobiliers, de l''étude du terrain à la réalisation.',
   'Nous portons et accompagnons des projets immobiliers : étude du terrain et du programme, préparation du site, coordination des travaux et suivi de la réalisation, en lien avec nos activités de BTP.'),
  ('amenagement-de-zones-residentielles-industrielles-et-agricoles',
   'Aménagement de zones résidentielles, industrielles ou agricoles : voiries, découpage et préparation des terrains.',
   'Nous aménageons des zones selon leur vocation, résidentielle, industrielle ou agricole : organisation du découpage, création des voiries, préparation des terrains et des accès, pour accueillir les futurs projets.'),
  ('accompagnement-des-investisseurs-et-partenaires-fonciers',
   'Accompagnement des investisseurs et partenaires dans leurs projets fonciers et immobiliers en Guinée.',
   'Nous accompagnons les investisseurs et partenaires qui souhaitent développer un projet foncier ou immobilier en Guinée : identification d''opportunités, présentation des sites et suivi des démarches sur le terrain.'),
  ('commercialisation-de-produits-et-marchandises-diverses',
   'Vente de produits et de marchandises diverses aux entreprises et aux particuliers.',
   'Nous commercialisons des produits et des marchandises variés pour répondre aux besoins des entreprises comme des particuliers. Décrivez-nous les articles recherchés et les quantités pour recevoir une proposition.'),
  ('fourniture-de-materiels-et-equipements',
   'Fourniture de matériels et d''équipements professionnels selon vos besoins.',
   'Nous fournissons des matériels et des équipements professionnels adaptés à votre activité. Précisez le type de matériel, les quantités et le lieu de livraison souhaité pour que nous établissions un devis.'),
  ('approvisionnement-des-entreprises-et-particuliers',
   'Approvisionnement régulier ou ponctuel des entreprises et des particuliers en produits et fournitures.',
   'Nous assurons l''approvisionnement des entreprises et des particuliers, de façon ponctuelle ou régulière : recherche des produits, regroupement des commandes et organisation de la livraison.'),
  ('importation-et-exportation-de-marchandises',
   'Importation et exportation de marchandises, avec l''organisation des formalités et de l''acheminement.',
   'Nous organisons l''importation et l''exportation de marchandises : recherche des produits, coordination de l''acheminement et suivi des formalités, pour faire parvenir vos marchandises à destination.'),
  ('recherche-de-fournisseurs-et-partenaires-internationaux',
   'Identification de fournisseurs et de partenaires à l''international pour vos besoins d''approvisionnement.',
   'Nous identifions pour vous des fournisseurs et des partenaires à l''international, et facilitons la mise en relation pour sécuriser vos approvisionnements en produits, matériaux ou équipements.'),
  ('negoce-commercial',
   'Achat et revente de marchandises pour répondre aux besoins du marché.',
   'Nous menons des activités de négoce : achat de marchandises auprès de fournisseurs et revente auprès de clients professionnels ou particuliers, selon les besoins exprimés.'),
  ('approvisionnement-en-equipements-materiaux-et-produits-divers',
   'Approvisionnement en équipements, matériaux et produits divers, en Guinée ou depuis l''étranger.',
   'Nous approvisionnons nos clients en équipements, matériaux et produits divers, disponibles localement ou importés. Indiquez-nous votre besoin pour que nous étudiions la solution d''approvisionnement la plus adaptée.')
) as v(slug, summary, description)
where s.slug = v.slug;
